<section aria-labelledby="browser-game-quests-heading"><h2 id="browser-game-quests-heading">Quests</h2>@if($message)<p role="status">{{ $message }}</p>@endif @forelse($quests as $quest)<article><h3>{{ $quest->name }}</h3><p>{{ $quest->slug }}</p><button type="button" wire:click="accept('{{ $quest->id }}')" wire:loading.attr="disabled">Accept quest</button><button type="button" wire:click="complete('{{ $quest->id }}')" wire:loading.attr="disabled">Complete quest</button><button type="button" wire:click="abandon('{{ $quest->id }}')" wire:loading.attr="disabled">Abandon quest</button></article>@empty<p role="status">No quests are available.</p>@endforelse</section>
